// Array keywords: items, additionalItems, contains, maxItems, minItems,
// uniqueItems. All apply only to array instances.

import { ValidationError } from '../errors.mjs';
import { deepEqual } from '../types.mjs';

export function* items(validator, value, instance, schema) {
  if (!validator.isType(instance, 'array')) return;

  if (Array.isArray(value)) {
    // Tuple form: each position is validated against the schema at the
    // same index (when present).
    for (let index = 0; index < Math.min(value.length, instance.length); index++) {
      yield* validator.descend(instance[index], value[index], index);
    }
  } else {
    // Single schema (object or boolean) applies to every element.
    for (let index = 0; index < instance.length; index++) {
      yield* validator.descend(instance[index], value, index);
    }
  }
}

export function* additionalItems(validator, value, instance, schema) {
  if (!validator.isType(instance, 'array')) return;

  // Only meaningful alongside the tuple form of items.
  if (!Array.isArray(schema.items)) return;

  for (let index = schema.items.length; index < instance.length; index++) {
    if (value === false) {
      yield new ValidationError(
        'Additional items are not allowed',
      );
    } else {
      yield* validator.descend(instance[index], value, index);
    }
  }
}

export function* contains(validator, value, instance, schema) {
  if (!validator.isType(instance, 'array')) return;

  for (const element of instance) {
    if (validator.isValidAgainst(element, value)) return;
  }
  yield new ValidationError(
    'None of the items are valid under the given schema',
  );
}

export function* maxItems(validator, value, instance, schema) {
  if (!validator.isType(instance, 'array')) return;

  if (instance.length > value) {
    yield new ValidationError('Too many items');
  }
}

export function* minItems(validator, value, instance, schema) {
  if (!validator.isType(instance, 'array')) return;

  if (instance.length < value) {
    yield new ValidationError('Too few items');
  }
}

export function* uniqueItems(validator, value, instance, schema) {
  if (!validator.isType(instance, 'array')) return;

  if (value === true && !allUnique(instance)) {
    yield new ValidationError('Has non-unique elements');
  }
}

// jsonschema._utils.uniq: Python equality semantics, where true == 1 and
// false == 0, so any pair that is deep-equal (after unbool-ing) counts
// as a duplicate.
function allUnique(instance) {
  for (let i = 0; i < instance.length; i++) {
    for (let j = i + 1; j < instance.length; j++) {
      if (deepEqual(instance[i], instance[j])) return false;
    }
  }
  return true;
}

