1	// ErrorTree: a tree of validation errors keyed by instance path.
2	// Mirrors jsonschema.exceptions.ErrorTree.
3	//
4	// Key semantic: at each tree node, errors are stored in a dict keyed by
5	// the *validator name*, so multiple errors at the same path produced by
6	// the same keyword collapse into one entry. `total_errors` therefore can
7	// be smaller than the number of errors the tree was built from.
8	
9	export class ErrorTree {
10	  constructor(errors = []) {
11	    this.errors = {};
12	    this._contents = new Map();
13	    this._instance = undefined;
14	
15	    for (const error of errors) {
16	      let container = this;
17	      for (const element of error.path) {
18	        container = container._getChild(element);
19	      }
20	      container.errors[error.validator] = error;
21	      container._instance = error.instance;
22	    }
23	  }
24	
25	  _getChild(element) {
26	    if (!this._contents.has(element)) {
27	      this._contents.set(element, new ErrorTree());
28	    }
29	    return this._contents.get(element);
30	  }
31	
32	  get total_errors() {
33	    let childErrors = 0;
34	    for (const child of this._contents.values()) {
35	      childErrors += child.total_errors;
36	    }
37	    return Object.keys(this.errors).length + childErrors;
38	  }
39	}

1	// Node.js (ESM) port of test18.py — JSON Schema Draft-7 error counting
