20	const tree = new ErrorTree(errors); // Build error tree
21	
22	// Navigate tree
23	const total = tree.total_errors; // Total errors in tree
24	
25	// Iterate multiple times
26	const first_pass = [...validator.iter_errors(instance)];
27	const second_pass = [...validator.iter_errors(instance)];
28	
29	// Check instance multiple times with different approaches
