// Array keywords: items, additionalItems, contains, maxItems, minItems,
// uniqueItems. All apply only to array instances.
//
// Semantics mirror jsonschema 4.23.0 (verified against its bytecode):
// - `descend` into a `false` subschema yields an error with an EMPTY path
//   (the path element is never prepended) and validator=None; `true`
//   subschemas yield nothing. We emulate that here instead of using
//   validator.descend for boolean subschemas.
// - `additionalItems: false` yields a single error no matter how many
//   extra items there are.
// - `uniqueItems` uses jsonschema._utils.uniq: a sorted-adjacent fast path
//   falling back to pairwise comparison, with an equality in which
//   booleans are rewritten to unique sentinels (True != 1, False != 0),
//   while numbers compare by value (1 == 1.0).

import { ValidationError } from '../errors.mjs';
import { deepEqual } from '../types.mjs';

export function* items(validator, value, instance, schema) {
  if (!validator.isType(instance, 'array')) return;

  if (Array.isArray(value)) {
    // Tuple form: zip positions with their subschemas (stops at the
    // shorter of the two).
    for (let index = 0; index < Math.min(value.length, instance.length); index++) {
      yield* descendElement(validator, instance[index], value[index], index);
    }
  } else {
    // Single schema (object or boolean) applies to every element.
    for (let index = 0; index < instance.length; index++) {
      yield* descendElement(validator, instance[index], value, index);
    }
  }
}

// validator.descend, but with jsonschema's boolean-schema behaviour:
// `true` yields nothing; `false` yields one error whose path is left
// empty (jsonschema's descend never prependls the path for booleans).
function* descendElement(validator, element, subschema, index) {
  if (subschema === true) return;
  if (subschema === false) {
    yield new ValidationError(
      `False schema does not allow ${JSON.stringify(element)}`,
    );
    return;
  }
  yield* validator.descend(element, subschema, index);
}

export function* additionalItems(validator, value, instance, schema) {
  if (!validator.isType(instance, 'array')) return;

  // Only meaningful alongside the tuple form of items (jsonschema bails
  // out when schema.items is missing or a schema).
  if (!Array.isArray(schema.items)) return;

  if (value !== null && typeof value === 'object') {
    for (let index = schema.items.length; index < instance.length; index++) {
      yield* validator.descend(instance[index], value, index);
    }
  } else if (!value && instance.length > schema.items.length) {
    // jsonschema yields a single error no matter how many extra items.
    yield new ValidationError('Additional items are not allowed');
  }
}

export function* contains(validator, value, instance, schema) {
  if (!validator.isType(instance, 'array')) return;

  for (const element of instance) {
    if (validator.isValidAgainst(element, value)) return;
  }
  yield new ValidationError(
    'None of the items are valid under the given schema',
  );
}

export function* maxItems(validator, value, instance, schema) {
  if (!validator.isType(instance, 'array')) return;

  if (instance.length > value) {
    yield new ValidationError('Too many items');
  }
}

export function* minItems(validator, value, instance, schema) {
  if (!validator.isType(instance, 'array')) return;

  if (instance.length < value) {
    yield new ValidationError('Too few items');
  }
}

export function* uniqueItems(validator, value, instance, schema) {
  if (!validator.isType(instance, 'array')) return;

  if (value === true && !uniq(instance)) {
    yield new ValidationError('Has non-unique elements');
  }
}

// --- jsonschema._utils.uniq / equal / unbool -------------------------

// unbool's sentinel replacements for True/False (function-default
// arguments in CPython, so they are shared singletons).
const UNBOOL_TRUE = Symbol('unbool-true');
const UNBOOL_FALSE = Symbol('unbool-false');

// jsonschema._utils.unbool: rewrites ONLY the top-level value.
function unbool(element) {
  if (element === true) return UNBOOL_TRUE;
  if (element === false) return UNBOOL_FALSE;
  return element;
}

// jsonschema._utils.uniq.
function uniq(container) {
  let sorted;
  try {
    sorted = pySorted(container.map(unbool));
  } catch (error) {
    if (!(error instanceof IncomparableValues)) throw error;
    // Slow fallback: pairwise comparison.
    const seen = [];
    for (const raw of container) {
      const element = unbool(raw);
      for (const previous of seen) {
        if (equal(previous, element)) return false;
      }
      seen.push(element);
    }
    return true;
  }
  // Fast path: only adjacent elements of the sorted container are compared.
  for (let i = 0; i + 1 < sorted.length; i++) {
    if (equal(sorted[i], sorted[i + 1])) return false;
  }
  return true;
}

// jsonschema._utils.equal: booleans are distinct from numbers (via
// unbool sentinels), numbers compare by value, sequences and mappings
// recurse element-wise.
function equal(one, two) {
  if (one === two) return true;
  if (typeof one === 'string' || typeof two === 'string') return one === two;
  if (Array.isArray(one) && Array.isArray(two)) {
    if (one.length !== two.length) return false;
    for (let i = 0; i < one.length; i++) {
      if (!equal(one[i], two[i])) return false;
    }
    return true;
  }
  if (isPlainObject(one) && isPlainObject(two)) {
    const keys = Object.keys(one);
    if (keys.length !== Object.keys(two).length) return false;
    for (const key of keys) {
      if (!Object.prototype.hasOwnProperty.call(two, key)) return false;
      if (!equal(one[key], two[key])) return false;
    }
    return true;
  }
  return unbool(one) === unbool(two);
}

function isPlainObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

// --- Python `sorted` emulation for the uniq fast path -----------------

class IncomparableValues extends Error {}

// Stable binary insertion sort, mirroring CPython's listsort for short
// arrays (< 64 elements): the same comparisons in the same order, so a
// TypeError (here IncomparableValues) is raised exactly when CPython's
// sort would raise one.
function pySorted(values) {
  const result = values.slice();
  for (let i = 1; i < result.length; i++) {
    const pivot = result[i];
    let lo = 0;
    let hi = i;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (pyLess(result[mid], pivot)) lo = mid + 1;
      else hi = mid;
    }
    for (let j = i; j > lo; j--) result[j] = result[j - 1];
    result[lo] = pivot;
  }
  return result;
}

// Python's `<` on JSON values; throws IncomparableValues where CPython
// would raise TypeError. Booleans (which survive inside nested
// arrays/objects) compare as their integer values, like Python.
function pyLess(one, two) {
  const a = one === true ? 1 : one === false ? 0 : one;
  const b = two === true ? 1 : two === false ? 0 : two;
  if (typeof a === 'number' && typeof b === 'number') return a < b;
  if (typeof a === 'string' && typeof b === 'string') return a < b;
  if (Array.isArray(a) && Array.isArray(b)) {
    const shared = Math.min(a.length, b.length);
    for (let i = 0; i < shared; i++) {
      // List ordering first scans for a pair that is not `==`
      // (Python `==` semantics, where true == 1), then compares it.
      if (!deepEqual(a[i], b[i])) return pyLess(a[i], b[i]);
    }
    return a.length < b.length;
  }
  throw new IncomparableValues();
}

